  const selectField=(label,id,values,value,extra='')=>'<div class="pia-field"><label for="'+id+'">'+label+'</label><select id="'+id+'" '+extra+'>'+opts(values,value)+'</select></div>';
  const heading=(title,caption)=>'<h2>'+title+'</h2><p class="pia-caption">'+caption+'</p>';
  const button=(label,action,primary=true,ico='',disabled=false)=>'<button type="button" class="'+(primary?'pia-primary':'pia-secondary-button')+'" data-action="'+action+'" '+(disabled?'disabled':'')+'>'+(ico?icon(ico):'')+label+'</button>';
  const check=(id,text,value,disabled=false)=>'<label class="pia-check"><input id="'+id+'" type="checkbox" '+(value?'checked':'')+' '+(disabled?'disabled':'')+'><span>'+text+'</span></label>';
  const note=text=>'<p class="pia-help">'+icon('info')+'<span>'+text+'</span></p>';
  const art=(side,editable=false,r=o())=>{const label=side==='front'?'Frente':'Espalda';return '<div class="pia-art-box"><div class="pia-art">'+(r.images[side]?'<img src="'+esc(r.images[side])+'" alt="Diseño '+label.toLowerCase()+'">':'<span class="pia-art-empty">'+(editable?'Agregar imagen':'Imagen pendiente')+'</span>')+'</div><div class="pia-art-label">'+label+'</div>'+(editable?'<div class="pia-art-file"><label for="pia-img-'+side+'">Reemplazar imagen</label><input id="pia-img-'+side+'" type="file" accept="image/*" data-image="'+side+'"></div>':'')+'</div>';};
  const orderArt=(r=o(),editable=false)=>'<div class="pia-primary-design">'+((r.additionalDesigns||[]).length?'<h3>Diseño principal</h3>':'')+'<div class="pia-art-grid">'+art('front',editable,r)+art('back',editable,r)+'</div></div>'+ProwayExtras.additionalDesigns(r,editable);
  const totals=r=>['Butarga','Playera','Short'].map(p=>{const a=r.rows.filter(x=>x.product===p);return a.length?'<div class="pia-account-line"><span>'+p+'</span><span>Hombre '+a.filter(x=>x.cut==='Hombre').reduce((s,x)=>s+x.qty,0)+' · Mujer '+a.filter(x=>x.cut==='Mujer').reduce((s,x)=>s+x.qty,0)+'</span></div>':'';}).join('');
