  function pickerUpdate(){picker.innerHTML=orders.map((r,i)=>r.quoteStatus==='discarded'&&i!==selected?'':'<option value="'+i+'" '+(i===selected?'selected':'')+'>'+r.id+' · '+esc(r.name)+(r.quoteStatus==='discarded'?' · descartada':r.quoteStatus==='cancelled'?' · cancelado':'')+'</option>').join('');}
  function announce(text){feedback.textContent=text;feedback.hidden=false;}
  function record(action,section='pedido',r=o()){activity.push({client:r.id,action,section,time:new Date().toLocaleTimeString('es-MX',{timeZone:'America/Mexico_City',hour:'2-digit',minute:'2-digit'})});if(appReady)ProwayPlatform.changed();}
